#define MOD 998244353LL

typedef long long ll;

typedef struct Node {
    int l, r;
    int val;              // digit if segment is uniform
    int lazy;             // -1 means no lazy
    ll num;               // numeric value of this segment modulo MOD
    struct Node *left, *right;
} Node;

static ll *pow10v;
static ll *ones;

// value of length len filled with digit d
static inline ll make_num(int len, int d) {
    return (ones[len] * d) % MOD;
}

static Node* build(int l, int r) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->l = l;
    node->r = r;
    node->lazy = -1;
    node->left = node->right = NULL;

    if (l == r) {
        node->val = 1;
        node->num = 1;
        return node;
    }

    int m = (l + r) >> 1;
    node->left = build(l, m);
    node->right = build(m + 1, r);
    node->val = 1;
    int right_len = r - m;
    node->num = (node->left->num * pow10v[right_len] + node->right->num) % MOD;
    return node;
}

static inline void apply(Node *node, int d) {
    node->val = d;
    node->lazy = d;
    node->num = make_num(node->r - node->l + 1, d);
}

static void push(Node *node) {
    if (node->lazy == -1 || node->l == node->r) return;
    apply(node->left, node->lazy);
    apply(node->right, node->lazy);
    node->lazy = -1;
}

static void pull(Node *node) {
    int right_len = node->right->r - node->right->l + 1;
    node->num = (node->left->num * pow10v[right_len] + node->right->num) % MOD;
}

static void update(Node *node, int ql, int qr, int d) {
    if (qr < node->l || node->r < ql) return;
    if (ql <= node->l && node->r <= qr) {
        apply(node, d);
        return;
    }
    push(node);
    update(node->left, ql, qr, d);
    update(node->right, ql, qr, d);
    pull(node);
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    pow10v = (ll*)malloc((N + 1) * sizeof(ll));
    ones = (ll*)malloc((N + 1) * sizeof(ll));

    pow10v[0] = 1;
    for (int i = 1; i <= N; i++) pow10v[i] = (pow10v[i - 1] * 10) % MOD;

    ones[0] = 0;
    for (int i = 1; i <= N; i++) ones[i] = (ones[i - 1] * 10 + 1) % MOD;

    Node *root = build(1, N);

    for (int i = 0; i < Q; i++) {
        int L, R, D;
        scanf("%d %d %d", &L, &R, &D);
        update(root, L, R, D);
        printf("%lld\n", root->num);
    }

    return 0;
}

