public class Main {
    static final int MOD = 998244353;

    static class SegmentTree {
        int n;
        long[] val;
        int[] lazy;
        long[] pow10;

        SegmentTree(int n) {
            this.n = n;
            val = new long[4 * n];
            lazy = new int[4 * n];
            Arrays.fill(lazy, -1);
            pow10 = new long[n + 1];
            pow10[0] = 1;
            for (int i = 1; i <= n; i++) {
                pow10[i] = (pow10[i - 1] * 10) % MOD;
            }
            build(1, 0, n - 1);
        }

        private void build(int idx, int l, int r) {
            if (l == r) {
                val[idx] = 1; // initially '1'
                return;
            }
            int mid = (l + r) / 2;
            build(idx * 2, l, mid);
            build(idx * 2 + 1, mid + 1, r);
            val[idx] = (val[idx * 2] * pow10[r - mid] + val[idx * 2 + 1]) % MOD;
        }

        private void apply(int idx, int l, int r, int digit) {
            lazy[idx] = digit;
            val[idx] = digit * (pow10[r - l + 1] - 1 + MOD) % MOD * inv9() % MOD;
        }

        private long inv9() {
            return powMod(9, MOD - 2);
        }

        private long powMod(long a, long e) {
            long res = 1;
            while (e > 0) {
                if ((e & 1) == 1) res = (res * a) % MOD;
                a = (a * a) % MOD;
                e >>= 1;
            }
            return res;
        }

        private void push(int idx, int l, int r) {
            if (lazy[idx] != -1) {
                int mid = (l + r) / 2;
                apply(idx * 2, l, mid, lazy[idx]);
                apply(idx * 2 + 1, mid + 1, r, lazy[idx]);
                lazy[idx] = -1;
            }
        }

        void update(int idx, int l, int r, int ql, int qr, int digit) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                apply(idx, l, r, digit);
                return;
            }
            push(idx, l, r);
            int mid = (l + r) / 2;
            update(idx * 2, l, mid, ql, qr, digit);
            update(idx * 2 + 1, mid + 1, r, ql, qr, digit);
            val[idx] = (val[idx * 2] * pow10[r - mid] + val[idx * 2 + 1]) % MOD;
        }

        long query() {
            return val[1];
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());
        SegmentTree seg = new SegmentTree(N);
