public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        char nextChar() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            return (char) c;
        }
    }

    static class SegTree {
        int n;
        long[] val;
        int[] lazy; // -1 means no lazy assignment
        long[] pow10;
        long[] ones;

        SegTree(int n, long[] pow10, long[] ones) {
            this.n = n;
            this.pow10 = pow10;
            this.ones = ones;
            val = new long[n << 2];
            lazy = new int[n << 2];
            Arrays.fill(lazy, -1);
            build(1, 1, n);
        }

        void build(int node, int l, int r) {
            if (l == r) {
                val[node] = 1;
                return;
            }
            int mid = (l + r) >> 1;
            build(node << 1, l, mid);
            build(node << 1 | 1, mid + 1, r);
            pull(node, r - mid);
        }

        void pull(int node, int rightLen) {
            val[node] = (val[node << 1] * pow10[rightLen] + val[node << 1 | 1]) % MOD;
        }

        void apply(int node, int l, int r, int digit) {
            int len = r - l + 1;
            val[node] = ones[len] * digit % MOD;
            lazy[node] = digit;
        }

        void push(int node, int l, int r) {
            if (lazy[node] == -1 || l == r) return;
            int mid = (l + r) >> 1;
            apply(node << 1, l, mid, lazy[node]);
            apply(node << 1 | 1, mid + 1, r, lazy[node]);
            lazy[node] = -1;
        }

        void update(int node, int l, int r, int ql, int qr, int digit) {
            if (ql <= l && r <= qr) {
                apply(node, l, r, digit);
                return;
            }
            push(node, l, r);
            int mid = (l + r) >> 1;
            if (ql <= mid) update(node << 1, l, mid, ql, qr, digit);
            if (qr > mid) update(node << 1 | 1, mid + 1, r, ql, qr, digit);
            pull(node, r - mid);
        }

        long allValue() {
            return val[1];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int Q = fs.nextInt();

        long[] pow10 = new long[N + 1];
        long[] ones = new long[N + 1];
        pow10[0] = 1;
        for (int i = 1; i <= N; i++) {
            pow10[i] = pow10[i - 1] * 10 % MOD;
        }
        for (int i = 1; i <= N; i++) {
            ones[i] = (ones[i - 1] * 10 + 1) % MOD;
        }

        SegTree st = new SegTree(N, pow10, ones);
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < Q; i++) {
            int l = fs.nextInt();
            int r = fs.nextInt();
            int d = fs.nextChar() - '0';
            st.update(1, 1, N, l, r, d);
            out.append(st.allValue()).append('\n');
        }

        System.out.print(out.toString());
    }
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int MAXN = 500005;

long long pw10[MAXN], repunit[MAXN];
long long inv9;

long long power(long long a, long long b, long long mod) {
    long long res = 1; a %= mod;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

struct Node {
    long long val;
    int lazy; // -1 means no lazy, 0-9 means assign digit
};

Node tree[4 * MAXN];
int n;

void build(int node, int l, int r) {
    tree[node].lazy = -1;
    if (l == r) { tree[node].val = 1; return; }
    int mid = (l + r) / 2;
    build(2*node, l, mid);
    build(2*node+1, mid+1, r);
    tree[node].val = (tree[2*node].val % MOD * pw10[r - mid] % MOD + tree[2*node+1].val) % MOD;
}

void pushdown(int node, int l, int r) {
    if (tree[node].lazy == -1) return;
    int mid = (l + r) / 2;
    int d = tree[node].lazy;
    tree[2*node].val = (long long)d * repunit[mid - l + 1] % MOD;
    tree[2*node].lazy = d;
    tree[2*node+1].val = (long long)d * repunit[r - mid] % MOD;
    tree[2*node+1].lazy = d;
    tree[node].lazy = -1;
}

void update(int node, int l, int r, int ql, int qr, int d) {
    if (ql <= l && r <= qr) {
        tree[node].val = (long long)d * repunit[r - l + 1] % MOD;
        tree[node].lazy = d;
        return;
    }
    pushdown(node, l, r);
    int mid = (l + r) / 2;
    if (ql <= mid) update(2*node, l, mid, ql, qr, d);
    if (qr > mid) update(2*node+1, mid+1, r, ql, qr, d);
    tree[node].val = (tree[2*node].val * pw10[r - mid] % MOD + tree[2*node+1].val) % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    pw10[0] = 1;
    for (int i = 1; i < MAXN; i++) pw10[i] = pw10[i-1] * 10 % MOD;
    inv9 = power(9, MOD - 2, MOD);
    repunit[0] = 0;
    for (int i = 1; i < MAXN; i++) repunit[i] = (pw10[i] - 1 + MOD) % MOD * inv9 % MOD;

    int q;
    cin >> n >> q;
    build(1, 1, n);

    while (q--) {
        int l, r; char c;
        cin >> l >> r >> c;
        int d = c - '0';
        update(1, 1, n, l, r, d);
        cout << tree[1].val << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

struct Node {
    int l, r;
    int digit;          // -1 if not uniform, otherwise assigned digit
    long long val;      // numeric value of this segment modulo MOD
};

int N, Q;
vector<Node> seg;
vector<long long> pow10mod, ones;

// value of length len filled with digit d
inline long long repeated_value(int len, int d) {
    return ones[len] * d % MOD;
}

void build(int idx, int l, int r) {
    seg[idx].l = l;
    seg[idx].r = r;
    if (l == r) {
        seg[idx].digit = 1;
        seg[idx].val = 1;
        return;
    }
    int mid = (l + r) >> 1;
    build(idx << 1, l, mid);
    build(idx << 1 | 1, mid + 1, r);
    seg[idx].digit = 1;
    int rightLen = r - mid;
    seg[idx].val = (seg[idx << 1].val * pow10mod[rightLen] + seg[idx << 1 | 1].val) % MOD;
}

void apply(int idx, int d) {
    seg[idx].digit = d;
    int len = seg[idx].r - seg[idx].l + 1;
    seg[idx].val = repeated_value(len, d);
}

void push(int idx) {
    if (seg[idx].digit != -1 && seg[idx].l != seg[idx].r) {
        apply(idx << 1, seg[idx].digit);
        apply(idx << 1 | 1, seg[idx].digit);
        seg[idx].digit = -1;
    }
}

void pull(int idx) {
    int left = idx << 1, right = idx << 1 | 1;
    int rightLen = seg[right].r - seg[right].l + 1;
    seg[idx].val = (seg[left].val * pow10mod[rightLen] + seg[right].val) % MOD;
    if (seg[left].digit == seg[right].digit && seg[left].digit != -1) seg[idx].digit = seg[left].digit;
    else seg[idx].digit = -1;
}

void update(int idx, int ql, int qr, int d) {
    int l = seg[idx].l, r = seg[idx].r;
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) {
        apply(idx, d);
        return;
    }
    push(idx);
    update(idx << 1, ql, qr, d);
    update(idx << 1 | 1, ql, qr, d);
    pull(idx);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> Q;

    pow10mod.assign(N + 1, 1);
    for (int i = 1; i <= N; i++) {
        pow10mod[i] = pow10mod[i - 1] * 10 % MOD;
    }

    ones.assign(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        ones[i] = (ones[i - 1] * 10 + 1) % MOD;
    }

    seg.resize(4 * N + 5);
    build(1, 1, N);

    for (int i = 0; i < Q; i++) {
        int L, R, D;
        cin >> L >> R >> D;
        update(1, L, R, D);
        cout << seg[1].val << '\n';
    }

    return 0;
}
